#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  /* The original loop order (i outer, j inner) already matches
     row-major layout, so we simply keep it. */
  for (i = 0; i < N; i++)
    {
      DATA_TYPE *row = data[i];
      for (j = 0; j < M; j++)
        row[j] = ((DATA_TYPE) i*j) / M;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Create restrict-qualified local pointers to help the compiler
     reason about aliasing and generate better code (vectorization,
     register allocation, etc.). */
  DATA_TYPE (*restrict data_)[m] = data;
  DATA_TYPE (*restrict cov_)[m]  = cov;
  DATA_TYPE *restrict mean_      = mean;

  /* Precompute scalar factors to avoid repeated divisions. */
  const DATA_TYPE inv_float_n   = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE normalization = SCALAR_VAL(1.0) /
                                  (float_n - SCALAR_VAL(1.0));

#pragma scop
  /* 1. Compute column means: mean[j] = (1/n) * sum_i data[i][j].
   *
   * The original code traversed the matrix column-wise (j outer, i inner),
   * which is strided for a row-major layout. Here we traverse row-wise
   * (i outer, j inner) to improve spatial locality.
   */

  /* Initialize means. */
  for (j = 0; j < _PB_M; ++j)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums with a row-major traversal. */
  for (i = 0; i < _PB_N; ++i)
    {
      DATA_TYPE *restrict row = data_[i];
      for (j = 0; j < _PB_M; ++j)
        mean_[j] += row[j];
    }

  /* Scale to obtain the mean values. */
  for (j = 0; j < _PB_M; ++j)
    mean_[j] *= inv_float_n;


  /* 2. Initialize the upper triangle of the covariance matrix.
   *
   * We only touch entries with j >= i; the lower triangle will be filled
   * later by symmetry, as in the original implementation.
   */
  for (i = 0; i < _PB_M; ++i)
    for (j = i; j < _PB_M; ++j)
      cov_[i][j] = SCALAR_VAL(0.0);


  /* 3. Center the data and accumulate the unnormalized covariance
   *    in a single pass over the rows.
   *
   * For each observation (row k), we:
   *   - subtract the mean from each component (centering in-place),
   *   - immediately use the centered row to update the covariance.
   *
   * This improves data locality compared with the original code, which
   * fully centered the matrix first and then made a separate pass to
   * compute the covariance. Here each row is brought into cache once
   * and reused right away for the covariance computation.
   */

  for (k = 0; k < _PB_N; ++k)
    {
      DATA_TYPE *restrict row = data_[k];

      /* Center current row: x_ij <- x_ij - mean_j. */
      for (j = 0; j < _PB_M; ++j)
        row[j] -= mean_[j];

      /* Accumulate contributions to the covariance matrix using
         the centered row. The inner j-loop is unit-stride in memory
         (row-major), which is friendly to vectorization and caching. */
      for (i = 0; i < _PB_M; ++i)
        {
          const DATA_TYPE xi = row[i];
          for (j = i; j < _PB_M; ++j)
            cov_[i][j] += xi * row[j];
        }
    }


  /* 4. Normalize and symmetrize the covariance matrix.
   *
   * cov[i][j] = cov[j][i] = (1 / (n - 1)) * sum_k
   *                            (data_centered[k][i] * data_centered[k][j])
   *
   * We delay the normalization until after the accumulation to trade
   * one division per element for a single precomputed multiplication
   * by "normalization". This preserves the mathematical result while
   * reducing the number of expensive division operations.
   */
  for (i = 0; i < _PB_M; ++i)
    for (j = i; j < _PB_M; ++j)
      {
        const DATA_TYPE c = cov_[i][j] * normalization;
        cov_[i][j] = c;
        cov_[j][i] = c;
      }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
