      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Use row-major traversals for better cache locality.
 *  - Precompute reciprocals of scalar denominators to avoid
 *    repeated divisions in inner loops.
 *  - Introduce restrict-qualified local aliases for the main
 *    arrays to help the compiler with vectorization and
 *    alias analysis.
 *  - Reorder covariance computation as a sequence of outer
 *    products (X^T * X) while still computing the full
 *    symmetric covariance matrix.
 *
 * The arithmetic performed is mathematically identical to
 * the original code (up to standard floating-point
 * round-off differences due to reordering of sums).
 */
static void __attribute__((noinline))
kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Local restrict-qualified aliases with explicit row size.
   * This gives the compiler precise information about the
   * layout and non-aliasing of the arrays, improving
   * vectorization and bounds reasoning.
   */
  DATA_TYPE (* __restrict data_)[m] = (DATA_TYPE (*)[m]) data;
  DATA_TYPE (* __restrict cov_)[m]  = (DATA_TYPE (*)[m]) cov;
  DATA_TYPE * __restrict mean_      = (DATA_TYPE *)      mean;

  /* Precompute constants to reduce the number of divisions
   * inside loops.
   */
  const DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE denom       = float_n - SCALAR_VAL(1.0);
  const DATA_TYPE inv_denom   = SCALAR_VAL(1.0) / denom;

#pragma scop
  /* ------------------------------------------------------------------
   * 1. Compute column means.
   *
   * Original code:
   *   for (j)
   *     mean[j] = 0;
   *     for (i)
   *       mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *
   * That accesses 'data' with a large stride (fixed column j, varying i),
   * which is unfriendly to caches in row-major layout.
   *
   * Here we:
   *   - First zero the mean vector.
   *   - Traverse 'data' row by row, accumulating into the means.
   *   - Finally scale by 1/float_n.
   *
   * This preserves the mathematical result while turning the data
   * access into a sequential, row-major traversal.
   * ------------------------------------------------------------------ */

  /* Initialize means to zero. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate each row into the column means (row-major access). */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict row = data_[i];
    for (j = 0; j < _PB_M; j++)
      mean_[j] += row[j];
  }

  /* Scale by 1/n. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] *= inv_float_n;

  /* ------------------------------------------------------------------
   * 2. Center the data by subtracting the mean from each column.
   *
   * This loop already uses row-major traversal; we simply make
   * that explicit with a row pointer and restrict-qualified
   * aliases.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict row = data_[i];
    for (j = 0; j < _PB_M; j++)
      row[j] -= mean_[j];
  }

  /* ------------------------------------------------------------------
   * 3. Compute covariance matrix.
   *
   * Original code (schematically):
   *   for (i)
   *     for (j = i; j < M; j++) {
   *       cov[i][j] = 0;
   *       for (k)
   *         cov[i][j] += data[k][i] * data[k][j];
   *       cov[i][j] /= (n - 1);
   *       cov[j][i] = cov[i][j];
   *     }
   *
   * That iterates over k innermost, reading data[k][i] and data[k][j]
   * with a large stride in memory (varying k, fixed i/j).
   *
   * Here we reformulate covariance as:
   *   cov = (1 / (n - 1)) * X^T * X,
   * where X is the centered data.
   *
   * Implementation:
   *   1) Initialize upper triangle of cov to 0.
   *   2) For each observation (row) k, accumulate its outer product
   *      into cov:
   *        cov[i][j] += data[k][i] * data[k][j]  (for j >= i)
   *      This uses row-major access to 'data'.
   *   3) Scale entries by 1 / (n - 1) and mirror to enforce symmetry.
   *
   * This reordering improves data locality while preserving the
   * mathematical result.
   * ------------------------------------------------------------------ */

  /* 3.1 Initialize upper-triangular part of covariance to zero. */
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE * __restrict cov_row_i = cov_[i];
    for (j = i; j < _PB_M; j++)
      cov_row_i[j] = SCALAR_VAL(0.0);
  }

  /* 3.2 Accumulate outer products of centered rows into the
   *      upper triangle of cov.
   *
   * For each row 'k', we read it once (row-major) and update
   * cov[i][j] for all j >= i. Each cov[i][j] is thus:
   *
   *   cov[i][j] = sum_{k=0..N-1} data[k][i] * data[k][j]
   */
  for (k = 0; k < _PB_N; k++)
  {
    DATA_TYPE * __restrict row = data_[k];

    for (i = 0; i < _PB_M; i++)
    {
      const DATA_TYPE r_i = row[i];
      DATA_TYPE * __restrict cov_row_i = cov_[i];

      /* j starts from i because cov is symmetric. */
      for (j = i; j < _PB_M; j++)
        cov_row_i[j] += r_i * row[j];
    }
  }

  /* 3.3 Scale by 1 / (n - 1) and fill the lower triangle to
   *      make cov explicitly symmetric.
   */
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE * __restrict cov_row_i = cov_[i];

    for (j = i; j < _PB_M; j++)
    {
      cov_row_i[j] *= inv_denom;
      cov_[j][i] = cov_row_i[j]; /* Enforce symmetry. */
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
