#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified local aliases for the main arrays to help
     the compiler with alias analysis and vectorization.
   - Reorder the mean-computation loops to traverse the data matrix
     row-wise (unit-stride), improving cache locality.
   - In the covariance computation, switch to a symmetric rank-k–style
     update with loop order (k -> i -> j). This:
       * keeps accesses to data[k][*] unit-stride along the inner loop,
       * reuses each data(k,i) value across all j >= i, roughly halving
         the number of loads from the data matrix.
   - Factor out the common denominator (float_n - 1.0) used for scaling
     the covariance matrix.
   - Keep the accumulation order over k for each cov(i,j) identical to
     the original code, thereby preserving floating-point semantics
     for every matrix element.
 */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Local restrict-qualified aliases to help the compiler optimize.
     The PolyBench allocation ensures that data, cov, and mean do not
     overlap, so this is a valid use of restrict. */
  DATA_TYPE (*restrict data_)[m] = data;
  DATA_TYPE (*restrict cov_)[m]  = cov;
  DATA_TYPE *restrict mean_      = mean;

#pragma scop
  /* ------------------------------------------------------------------ */
  /* 1. Compute column means                                             */
  /* ------------------------------------------------------------------ */
  /* First, zero the means. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate means row by row. This loop ordering (i outer, j inner)
     accesses data_[i][j] with unit stride along the inner loop, which
     is more cache-friendly than the original column-wise traversal. */
  for (i = 0; i < _PB_N; i++)
  {
    const DATA_TYPE *restrict data_i = data_[i];
    for (j = 0; j < _PB_M; j++)
      mean_[j] += data_i[j];
  }

  /* Final division to obtain the average for each column. The order of
     additions for each mean_[j] is identical to the original code:
     data[0][j], data[1][j], ..., data[N-1][j]. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] /= float_n;

  /* ------------------------------------------------------------------ */
  /* 2. Center the data matrix (subtract the column means)              */
  /* ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *restrict data_i = data_[i];
    /* Inner loop is unit-stride over the row. */
    for (j = 0; j < _PB_M; j++)
      data_i[j] -= mean_[j];
  }

  /* ------------------------------------------------------------------ */
  /* 3. Compute the covariance matrix                                   */
  /* ------------------------------------------------------------------ */
  const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);

  /* 3a. Initialize the upper-triangular part of covariance to zero.
         The lower triangle will be filled later via symmetry, so it
         does not need initialization. */
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE *restrict cov_i = cov_[i];
    for (j = i; j < _PB_M; j++)
      cov_i[j] = SCALAR_VAL(0.0);
  }

  /* 3b. Accumulate the unscaled covariance matrix.
     We perform a symmetric rank-k like update:
       cov(i,j) += data(k,i) * data(k,j)
     for all k, with i <= j.

     Loop order is (k -> i -> j):
       - For fixed k, data_[k][*] is accessed with unit stride along the
         inner j loop.
       - For each (k,i), data(k,i) is loaded once into x_ki and reused
         across all j >= i.
       - For each cov(i,j), the contributions are added in the same
         order of k (0 .. N-1) as in the original code. */
  for (k = 0; k < _PB_N; k++)
  {
    const DATA_TYPE *restrict data_k = data_[k];

    for (i = 0; i < _PB_M; i++)
    {
      const DATA_TYPE x_ki = data_k[i];
      DATA_TYPE *restrict cov_i = cov_[i];

      /* Inner loop writes cov_i[j] for j >= i. These are independent
         across j and suitable for vectorization. */
      #pragma GCC ivdep
      for (j = i; j < _PB_M; j++)
        cov_i[j] += x_ki * data_k[j];
    }
  }

  /* 3c. Scale by the denominator and enforce symmetry.
     After step 3b, cov(i,j) holds:
       sum_{k=0}^{N-1} data(k,i) * data(k,j)
     for j >= i, and the lower triangle is undefined. We now divide by
     (float_n - 1.0) and mirror the upper triangle into the lower one. */
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE *restrict cov_i = cov_[i];

    /* Diagonal element. */
    cov_i[i] /= denom;

    /* Off-diagonal elements. */
    for (j = i + 1; j < _PB_M; j++)
    {
      cov_i[j] /= denom;
      cov_[j][i] = cov_i[j];
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
