static
void kernel_covariance [[gnu::flatten, gnu::noinline]] (int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Create local restrict-qualified aliases to make aliasing
   * relationships explicit and enable better vectorization.
   * PolyBench guarantees that these arrays do not overlap.
   */
  DATA_TYPE (*restrict data_)[m] = data;
  DATA_TYPE (*restrict cov_)[m]  = cov;
  DATA_TYPE *restrict mean_      = mean;

#pragma scop
  /* 1. Compute the mean of each column.
   *
   * Original structure (column-major accumulation):
   *   for (j)
   *     mean[j] = 0;
   *     for (i) mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *
   * Optimized structure:
   *   - Initialize mean[j] to zero.
   *   - Accumulate using a row-major traversal of `data` to improve
   *     cache locality.
   *   - Divide by float_n.
   *
   * For each column j, the sequence of additions over i is identical
   * to the original implementation; only operations for different
   * columns are interleaved, which does not change the result.
   */

  /* Initialize means to zero. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums with a row-major traversal of `data`. */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *restrict data_row = data_[i];
      for (j = 0; j < _PB_M; j++)
        mean_[j] += data_row[j];
    }

  /* Final division by float_n for each mean. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] /= float_n;

  /* 2. Center the data matrix by subtracting the column means.
   *
   * We again traverse `data` in row-major order to maximize spatial
   * locality.  Each element data[i][j] is touched exactly once.
   */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *restrict data_row = data_[i];
      for (j = 0; j < _PB_M; j++)
        data_row[j] -= mean_[j];
    }

