   *
   * Mathematical definition:
   *   cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
   *
   * Original code computed, for each (i,j), a separate scan over k,
   * repeatedly traversing the same columns in a strided pattern.
   *
   * Here we use a row-wise outer-product formulation:
   *   - For each row k, load it once.
   *   - Update all (i,j) pairs using that row.
   *
   * This greatly improves locality: each row of `data` is read once
   * and reused for all i,j pairs, while the small covariance matrix
   * stays in cache.  For each (i,j), contributions from different k
   * values are accumulated in the same order as in the original code.
   */

  /* Initialize covariance matrix to zero. */
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_M; j++)
      cov_[i][j] = SCALAR_VAL(0.0);

  /* Accumulate outer products of centered rows:
   *   cov[i][j] += data[k][i] * data[k][j]
   * for all 0 <= i <= j < M and 0 <= k < N.
   */
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE *restrict row = data_[k];

      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE r_i = row[i];

          /* Only compute the upper triangle (including the diagonal);
           * we'll mirror it later to fill the lower triangle.
           */
          for (j = i; j < _PB_M; j++)
            cov_[i][j] += r_i * row[j];
        }
    }

  /* Scale by (float_n - 1) and explicitly symmetrize the matrix.
   * The denominator is computed once and reused; each element still
   * performs exactly one division by the same value as in the
   * original implementation.
