      cov_[i][i] /= denom;

      /* Off-diagonal elements: compute once in the upper triangle and
       * copy to the symmetric position.
       */
      for (j = i + 1; j < _PB_M; j++)
        {
          cov_[i][j] /= denom;
          cov_[j][i] = cov_[i][j];
        }
    }
